if s.count(demo_cta) != 2:
    raise SystemExit(f"ปุ่มเปิดเดโม: ต้องเจอ 2 ครั้ง แต่เจอ {s.count(demo_cta)}")
s = s.replace(demo_cta, "เปิดเดโมให้ทีมลองใช้")
swap("ลองกดเล่นเลย ↓", "เริ่มจากเส้นทางของแขก", "ปุ่มเริ่มเรื่อง")
