for old, new in leads.items():
    swap(f'<p class="lead">{old}</p>', f'<p class="lead">{new}</p>', f"lead {old[:24]}")


# ปิดเรื่องด้วยคำชวนที่เหมาะกับการพรีเซนต์ต่อทีมโรงแรม
swap("เห็นหน้าจอจริงแล้ว ลองกดเองดู", "ลองให้ทีมของคุณเดินงานจริงหนึ่งรอบ", "หัวข้อปิด")
swap(
    "เดโมเปิดให้กดได้ทุกปุ่มโดยไม่ต้องสมัคร — จองห้องฝั่งแขก เช็กอินที่เคาน์เตอร์\n      สั่งอาหารเข้าบิล แล้วดูตัวเลขขยับในจอเจ้าของ ครบทั้ง 5 มุมมองในเดโมเดียว",
    "เริ่มจากรับจองหนึ่งห้อง เช็กอินที่เคาน์เตอร์ ส่งค่าอาหารเข้าบิล แล้วเปิดจอเจ้าของดูว่าตัวเลขเปลี่ยนอย่างไร "
    "ทีมทดลองได้ครบทั้งห้ามุมมองโดยไม่ต้องสมัคร",
    "ข้อความปิด",
)
swap("กลับไปหน้าหลัก ↗", "ดูภาพรวม Sentiara", "ปุ่มหน้าหลัก")


# ต่อชั้นดีไซน์หลัง ASTRA เพื่อให้ลำดับ cascade ชัดเจน
style = "\n\n<style>\n" + css + "\n</style>"
at = s.rfind("</style>")
if at < 0:
    raise SystemExit("ไม่พบ style หลัก")
s = s[:at + len("</style>")] + style + s[at + len("</style>"):]

DEST.write_text(s, encoding="utf-8")

checks = {
    "ชั้น ATELIER": "ATELIER — modern Thai hospitality" in s,
    "ภาพปกฝังแล้ว": "{{HERO_IMAGE}}" not in s and "deluxe-2.jpg" not in s,
    "หัวข้อครบ": len(re.findall(r'<section class="grp" id="g\d\d"', s)) == 14,
    "เดโมครบ": len(re.findall(r'id="p-[a-z]+"', s)) == 8,
    "เรื่องใหม่": "โรงแรมทั้งหลัง" in s and "ทีมของคุณเดินงานจริง" in s,
}
print(f"เสร็จ · {DEST.stat().st_size / 1024 / 1024:.2f} MB")
for label, ok in checks.items():
    print(f"   {'ผ่าน' if ok else 'ไม่ผ่าน ✗'}  {label}")
if not all(checks.values()):
    raise SystemExit("ประกอบชั้น ATELIER ไม่ครบ")
